const $=id=>document.getElementById(id);
const state={companies:[],company:null,role:null,current:null,product:'EXPRESS'};
const labels={DRAFT:'Черновик',SUBMITTED:'Подана',DATA_CHECK:'Проверка данных',SCORING:'Оценка риска',NEED_INFO:'Нужна доработка',MANUAL_REVIEW:'Ручная проверка',APPROVED:'Одобрено',COUNTER_OFFER:'Контрпредложение',REJECTED:'Отказ',SIGNING:'Подписание',ISSUED:'Выдано',CLOSED:'Закрыта'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(v||0);
const date=v=>new Date(v).toLocaleString('ru-RU');
function notice(message,success=false){$('notice').textContent=message;$('notice').className='notice'+(success?' success':'');$('notice').hidden=false;window.scrollTo({top:0,behavior:'smooth'})}
async function api(path,options={}){const form=options.body instanceof FormData;const res=await fetch(path,{...options,credentials:'same-origin',headers:form?{}:{'Content-Type':'application/json',...options.headers}});const raw=await res.text();let data;try{data=raw?JSON.parse(raw):{}}catch{throw Error('Сервис вернул некорректный ответ')}if(!res.ok)throw Error(data.message||data.error?.message||`Ошибка ${res.status}`);return data}
function view(name){for(const x of ['new','list','detail'])$(x+'-view').hidden=x!==name;$('welcome').hidden=name!=='new';$('nav-new').classList.toggle('active',name==='new');$('nav-list').classList.toggle('active',name!=='new');$('notice').hidden=true}
function product(p){state.product=p;document.querySelectorAll('[data-product]').forEach(el=>el.classList.toggle('selected',el.dataset.product===p));const eq=p==='EQUIPMENT';$('equipment-field').hidden=!eq;$('document-field').hidden=!eq;$('equipment-cost').required=eq;$('amount').min=eq?500000:300000;$('amount').max=eq?15000000:5000000;$('term').min=eq?12:6;$('term').max=eq?60:36;$('amount-hint').textContent=eq?'От 500 000 до 15 000 000 ₽':'От 300 000 до 5 000 000 ₽'}
function fillCompany(c){state.company=c;const r=c.demo_request;$('company-name').textContent=c.name;$('company-info').textContent='ИНН '+c.inn+' · Данные из локального симулятора';product(r.product);$('amount').value=r.amount;$('term').value=r.term_months;$('purpose').value=r.product==='EQUIPMENT'?'Покупка оборудования':'Закупка товара';$('revenue').value=r.annual_revenue;$('equipment-cost').value=r.equipment_cost||7000000;$('consent').checked=true;$('document').value=''}
async function login(role){try{const c=state.companies.find(c=>c.inn===$('company-select').value);await api('/demo/login',{method:'POST',body:JSON.stringify({role,inn:c.inn})});state.role=role;fillCompany(c);$('login-panel').hidden=true;$('account-button').textContent=role==='analyst'?'Сотрудник банка · сменить':c.name+' · сменить';$('nav-new').hidden=role==='analyst';$('nav-list').innerHTML=role==='analyst'?'▤ Очередь заявок':'▤ Мои заявки <span id="count">0</span>';$('list-title').textContent=role==='analyst'?'Очередь заявок':'Мои заявки';if(role==='analyst'){await list()}else{view('new')}}catch(e){notice(e.message)}}
async function list(){view('list');try{const all=await api('/applications');if($('count'))$('count').textContent=all.length;$('application-list').innerHTML=all.length?all.map(a=>`<article class="application-row" data-id="${a.application_id}" tabindex="0" role="button"><div><strong>${esc(a.company_name)} · № ${a.application_id}</strong><small>${a.product==='EXPRESS'?'На любые цели':'На оборудование'} · ${money(a.amount)} · ${a.term_months} мес.</small></div><span class="badge ${esc(a.status)}">${esc(labels[a.status]||a.status)}</span></article>`).join(''):'<div class="empty">Здесь появятся ваши заявки</div>';document.querySelectorAll('[data-id]').forEach(el=>{el.onclick=()=>detail(el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter')detail(el.dataset.id)}})}catch(e){notice(e.message)}}
async function upload(file){const f=new FormData();f.append('file',file);return(await api('/documents',{method:'POST',body:f})).document_id}
$('application-form').onsubmit=async e=>{e.preventDefault();const button=$('submit-button');button.disabled=true;button.textContent='Отправляем…';try{const eq=state.product==='EQUIPMENT';let doc=null;if(eq&&$('document').files[0])doc=await upload($('document').files[0]);const body={inn:state.company.inn,product:state.product,amount:Number($('amount').value),term_months:Number($('term').value),purpose:$('purpose').value,annual_revenue:Number($('revenue').value),bki_consent:$('consent').checked,equipment_cost:eq?Number($('equipment-cost').value):null,supplier_document_id:doc};const a=await api('/applications',{method:'POST',body:JSON.stringify(body)});await api(`/applications/${a.application_id}/submit`,{method:'POST'});try{await api(`/applications/${a.application_id}/process`,{method:'POST'})}catch(err){await detail(a.application_id);notice('Заявка сохранена. '+err.message);return}await detail(a.application_id)}catch(err){notice(err.message)}finally{button.disabled=false;button.innerHTML='Отправить заявку <span>→</span>'}};
async function detail(id){view('detail');try{const [a,history]=await Promise.all([api(`/applications/${id}/detail`),api(`/applications/${id}/history`)]);state.current=a;const d=a.decision||{};const o=d.offer;const client=state.role==='client';let actions='';
if(client){if(a.status==='DRAFT')actions+='<button class="primary" data-action="submit">Подать заявку →</button>';if(a.status==='SUBMITTED')actions+='<button class="primary" data-action="process">Продолжить рассмотрение →</button>';if(['APPROVED','COUNTER_OFFER'].includes(a.status))actions+='<button class="primary" data-action="accept-offer">Принять условия →</button>';if(a.status==='COUNTER_OFFER')actions+='<button class="secondary" data-action="decline-offer">Отклонить предложение</button>';if(a.status==='SIGNING')actions+='<button class="primary" data-action="sign">Условно подписать и получить кредит →</button>';if(['DRAFT','SUBMITTED','NEED_INFO','MANUAL_REVIEW'].includes(a.status))actions+='<button class="secondary" data-action="withdraw">Отозвать заявку</button>'}
let extra='';if(client&&a.status==='NEED_INFO')extra=`<div class="analyst-form"><h2>Дополните заявку</h2><label class="checkbox"><input id="revise-consent" type="checkbox" ${a.bki_consent?'checked':''}><span>Согласен на запрос БКИ</span></label>${a.product==='EQUIPMENT'?'<label>Документ поставщика<input id="revise-file" type="file" accept=".pdf,.txt,.png,.jpg,.jpeg"></label>':''}<button class="primary" style="margin-top:18px" id="revise-button">Сохранить и повторить проверки →</button></div>`;
if(!client&&a.status==='MANUAL_REVIEW')extra=`<form id="manual-form" class="analyst-form"><h2>Решение сотрудника</h2><p class="meta">Рекомендация: ${esc(labels[d.recommendation]||d.recommendation||'Нужны данные')}. Лимит: ${money(d.limit?.amount)}. Триггеры: ${esc((d.manual_review_triggers||[]).join(', '))}</p><div class="form-grid"><label>Решение<select id="manual-decision"><option value="APPROVED">Одобрить</option><option value="COUNTER_OFFER">Контрпредложение</option><option value="NEED_INFO">Запросить данные</option><option value="REJECTED">Отказать</option></select></label><label>Сумма, ₽<input id="manual-amount" type="number" min="0" max="${Number(d.limit?.amount||0)}" value="${Number(o?.amount||d.review_terms?.amount||0)}"></label><label>Код причины (при отказе)<select id="manual-reason"><option value="">Выберите причину</option>${Object.entries({R01:'Возраст бизнеса',R02:'Долговая нагрузка',R03:'Прошлые просрочки',R04:'Кредитный рейтинг',R05:'Сумма / выручка',R06:'Отраслевой риск',R07:'Массовый адрес',R08:'Долг приставам',R09:'Отчётность',R10:'Низкая выручка',R11:'Лимит залога'}).map(([k,v])=>`<option value="${k}">${k} · ${v}</option>`).join('')}</select></label><label>Комментарий<textarea id="manual-comment" required rows="2"></textarea></label></div><button class="primary" type="submit" style="margin-top:18px">Сохранить решение</button></form>`;
const next={MANUAL_REVIEW:'Сотрудник проверит данные и документы. Решение появится здесь.',REJECTED:'Ознакомьтесь с причинами решения ниже.',NEED_INFO:'Для продолжения нужны дополнительные сведения.',APPROVED:'Условия готовы. Примите их, чтобы перейти к подписанию.',COUNTER_OFFER:'Можем предложить другие условия. Выберите следующий шаг.',SIGNING:'Подтверждение подписи и выдача в этом прототипе смоделированы.',ISSUED:'Кредит условно выдан. Сквозной сценарий завершён.',CLOSED:'Рассмотрение этой заявки завершено.'};
$('detail').innerHTML=`<div class="detail-heading"><div><h1>Заявка № ${a.application_id}</h1><p>${esc(a.company_name)} · ${esc(a.inn)}</p></div><span class="badge ${esc(a.status)}">${esc(labels[a.status]||a.status)}</span></div><div class="card"><h2>${a.product==='EXPRESS'?'На любые цели бизнеса':'На оборудование'}</h2><p class="intro" style="margin:12px 0 0">${esc(next[a.status]||'Заявка проходит рассмотрение.')}</p><div class="metrics"><div class="metric"><small>${o?'Предлагаемая сумма':'Запрошенная сумма'}</small><strong>${money(o?.amount??a.amount)}</strong></div><div class="metric"><small>Срок кредита</small><strong>${o?.term_months??a.term_months} мес.</strong></div><div class="metric"><small>${o?'Ставка / платёж в месяц':'Цель'}</small><strong style="font-size:${o?22:15}px">${o?`${o.rate}%`:esc(a.purpose)}</strong>${o?`<small style="margin:8px 0 0">${money(o.monthly_payment)} / мес.</small>`:''}</div></div>${(d.reasons||[]).length?'<div class="reasons">'+d.reasons.map(r=>`<div><strong>${esc(r.code)}</strong> · ${esc(r.message)}</div>`).join('')+'</div>':''}${a.scoring_error?`<div class="notice">Техническая ошибка: ${esc(a.scoring_error)}</div>`:''}<div class="actions">${actions}</div>${extra}<details class="meta"><summary>Сведения о рассмотрении</summary><p>Класс риска: ${esc(d.grade||'Не рассчитан')} · ${d.pd!=null?'PD за 12 месяцев: '+(d.pd*100).toFixed(2)+'%':'Модель не вызывалась'}<br>Режим: ${esc(d.scoring_mode||'—')}<br>Версия правил: ${esc(d.policy_version||'—')}<br>Модель: ${esc(d.model_id||'—')}<br>Обучение: синтетические данные. Результат не является решением реального банка.</p></details></div><h2 class="history-title">История заявки</h2><ul class="timeline">${history.map(h=>`<li>${esc(labels[h.to_status]||h.to_status)}<small>${date(h.created_at)} · ${esc(h.actor)}</small></li>`).join('')||'<li>Черновик создан<small>'+date(a.created_at)+'</small></li>'}</ul>`;
if(!client && a.supplier_document_id){const box=document.createElement('div');box.className='actions';const link=document.createElement('a');link.className='secondary';link.href='/documents/'+encodeURIComponent(a.supplier_document_id);link.textContent='Скачать документ поставщика';box.append(link);$('detail').append(box)}
if(!client && a.decision){
const panel=document.createElement('section');panel.className='card';panel.id='analyst-evidence';
panel.innerHTML=`<h2>Скоринг и проверка данных</h2><div class="metrics"><div class="metric"><small>${d.scoring_mode==='points_fallback'?'Условная PD резервных правил':'PD модели за 12 месяцев'}</small><strong>${d.pd!=null?(Number(d.pd)*100).toFixed(2)+'%':'Не рассчитана'}</strong></div><div class="metric"><small>Класс риска</small><strong>${esc(d.grade||'Не рассчитан')}</strong></div><div class="metric"><small>Баллы правил (0–100)</small><strong>${d.score!=null?esc(d.score):'Не применялись'}</strong></div></div><p class="meta">PD — вероятность дефолта: меньше означает ниже риск. Баллы правил — отдельная шкала: больше означает лучше. ${d.scoring_mode==='not_scored'?'Модель не вызывалась; проверьте причины и стоп-факторы.':d.scoring_mode==='points_fallback'?'Резервные правила; это не прогноз CatBoost.':'Результат CatBoost на синтетических данных.'}</p><button type="button" class="secondary" id="verify-data">Проверить данные в базе</button><div id="verification-result" style="margin-top:18px"></div>`;
$('detail').querySelector('.card').after(panel);
$('verify-data').onclick=async()=>{const b=$('verify-data');b.disabled=true;try{
const audit=await api('/applications/'+id+'/audit'),v=audit.verification||{},s=audit.sources||{},c=s.company||{},f=s.financial_profile||{},bki=s.bki_profile||{},checks=s.business_checks||{};
const rows=[['Дата регистрации в снимке',v.registration_date||c.registration_date||'Нет данных'],['Дата рассмотрения',v.checked_at?date(v.checked_at):'Нет данных'],['Возраст на дату рассмотрения',v.age_months!=null?v.age_months+' полных мес.':'Нет данных'],['Стоп-фактор SF03: возраст менее 3 месяцев',v.age_stop_triggered==null?'Нет данных':v.age_stop_triggered?'Сработал':'Не сработал'],['Дата регистрации сейчас в БД',v.current_company?.registration_date?.slice(0,10)||'Нет данных'],['Снимок совпадает с текущей датой в БД',v.registration_matches_current_db==null?'Нет данных':v.registration_matches_current_db?'Да':'Нет — данные изменились после рассмотрения'],['Статус компании в снимке',c.status||'Нет данных'],['ОКВЭД в снимке',c.okved||'Нет данных'],['Выручка из финансового профиля',f.verified_annual_revenue!=null?money(f.verified_annual_revenue):'Нет данных'],['Кредитный рейтинг БКИ',bki.rating??'Нет данных'],['Текущая просрочка, дней',bki.current_overdue_days??'Нет данных'],['Дата профиля БКИ',bki.bki_as_of_date||'Нет данных'],['Дисквалификация руководителя',checks.director_disqualified==null?'Нет данных':checks.director_disqualified?'Да':'Нет']];
$('verification-result').innerHTML='<p class="meta">Проверка сохранённых синтетических данных PostgreSQL, без обращения к реальным реестрам. Возраст рассчитан на дату подачи, а не на сегодня. Причина R01 от SHAP отражает вклад признака модели и не равна стоп-фактору SF03.</p><dl>'+rows.map(([k,val])=>`<dt style="margin-top:12px;font-weight:600">${esc(k)}</dt><dd style="margin:4px 0">${esc(val)}</dd>`).join('')+'</dl>';
const fold=document.createElement('details');fold.className='meta';const title=document.createElement('summary');title.textContent='Полный снимок источников и ответ модели';const pre=document.createElement('pre');pre.style.whiteSpace='pre-wrap';pre.style.overflowWrap='anywhere';pre.textContent=JSON.stringify(audit,null,2);fold.append(title,pre);$('verification-result').append(fold);
}catch(e){$('verification-result').textContent=e.message}finally{b.disabled=false}};
}
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api(`/applications/${id}/${b.dataset.action}`,{method:'POST'});if(b.dataset.action==='submit')await api(`/applications/${id}/process`,{method:'POST'});await detail(id)}catch(e){notice(e.message);b.disabled=false}});
if($('revise-button'))$('revise-button').onclick=async()=>{const b=$('revise-button');b.disabled=true;try{const body={bki_consent:$('revise-consent').checked};const f=$('revise-file')?.files[0];if(f)body.supplier_document_id=await upload(f);await api(`/applications/${id}`,{method:'PATCH',body:JSON.stringify(body)});await api(`/applications/${id}/process`,{method:'POST'});await detail(id)}catch(e){notice(e.message);b.disabled=false}};
if($('manual-form')){
const select=$('manual-decision'),amount=$('manual-amount'),reason=$('manual-reason');
const minimum=a.product==='EQUIPMENT'?500000:300000;
const maximum=Math.min(Number(d.limit?.amount||0),Number(a.amount));
const canOffer=Boolean(o||d.review_terms)&&maximum>=minimum;
select.querySelector('[value="APPROVED"]').disabled=!canOffer||Number(a.amount)>Number(d.limit?.amount||0);
select.querySelector('[value="COUNTER_OFFER"]').disabled=!canOffer;
const hint=document.createElement('p');hint.id='manual-hint';hint.className='meta';select.closest('.form-grid').before(hint);
select.value=d.recommendation||'NEED_INFO';if(select.selectedOptions[0]?.disabled||!select.value)select.value='NEED_INFO';
const sync=()=>{
const value=select.value,offering=['APPROVED','COUNTER_OFFER'].includes(value);
amount.disabled=!offering;amount.required=offering;amount.closest('label').hidden=!offering;
amount.readOnly=value==='APPROVED';amount.min=String(minimum);amount.max=String(maximum);
if(value==='APPROVED')amount.value=String(a.amount);
else if(offering&&(!Number(amount.value)||Number(amount.value)>maximum))amount.value=String(Math.min(Number(o?.amount||d.review_terms?.amount||maximum),maximum));
reason.disabled=value!=='REJECTED';reason.required=value==='REJECTED';reason.closest('label').hidden=value!=='REJECTED';
hint.textContent=!canOffer?'По сохранённым данным нет доступной суммы в пределах ограничений продукта, выручки, долговой нагрузки и залога. Для предложения нужны уточнённые данные.':(value==='APPROVED'?'Одобрение сохраняет запрошенную сумму. Чтобы изменить сумму, выберите контрпредложение. Изменение рекомендации модели сохраняется в аудите.':value==='COUNTER_OFFER'?`Укажите сумму от ${money(minimum)} до ${money(maximum)} — в пределах лимита и запрошенной суммы. Изменение рекомендации модели сохраняется в аудите.`:value==='REJECTED'?'Укажите причину отказа и комментарий. Сумма для отказа не требуется.':'Укажите в комментарии, какие данные необходимо предоставить. Сумма и причина отказа не требуются.');
};select.onchange=sync;sync();
$('manual-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api(`/applications/${id}/decision`,{method:'POST',body:JSON.stringify({decision:select.value,amount:amount.disabled?0:Number(amount.value),reason_code:reason.disabled?'':reason.value,comment:$('manual-comment').value})});await detail(id)}catch(e){notice(e.message);b.disabled=false}};
}
}catch(e){notice(e.message)}}
$('login-client').onclick=()=>login('client');$('login-analyst').onclick=()=>login('analyst');$('nav-new').onclick=()=>{if(state.role)view('new');else $('login-panel').hidden=false};$('nav-list').onclick=()=>state.role?list():notice('Сначала выберите учётную запись');$('refresh').onclick=list;$('back-list').onclick=list;$('account-button').onclick=()=>{view('new');$('new-view').hidden=true;$('login-panel').hidden=false};document.querySelectorAll('[data-product]').forEach(el=>el.onclick=()=>product(el.dataset.product));
(async()=>{try{state.companies=await api('/companies');$('company-select').innerHTML=state.companies.map(c=>`<option value="${esc(c.inn)}">${esc(c.name)} · ${esc(c.inn)}</option>`).join('')}catch(e){notice('Не удалось загрузить компании. '+e.message)}})();
